package com.orderflow.notification.error;import com.orderflow.notification.correlation.NotificationRequestAttributes;import com.orderflow.platform.error.*;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.List;import org.slf4j.*;import org.springframework.http.*;import org.springframework.validation.BindException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class GlobalExceptionHandler{private static final Logger LOG=LoggerFactory.getLogger(GlobalExceptionHandler.class);@ExceptionHandler(NotificationDomainException.class)ResponseEntity<ApiError>domain(NotificationDomainException e,HttpServletRequest r){return make(e.status(),e.code(),e.getMessage(),r,List.of());}@ExceptionHandler({MethodArgumentNotValidException.class,BindException.class})ResponseEntity<ApiError>validation(Exception e,HttpServletRequest r){var b=e instanceof MethodArgumentNotValidException m?m.getBindingResult():((BindException)e).getBindingResult();return make(HttpStatus.BAD_REQUEST,ErrorCode.VALIDATION_ERROR,"Request validation failed",r,b.getFieldErrors().stream().map(x->new FieldViolation(x.getField(),x.getDefaultMessage(),null)).toList());}@ExceptionHandler(Exception.class)ResponseEntity<ApiError>unexpected(Exception e,HttpServletRequest r){LOG.error("Unexpected notification request failure",e);return make(HttpStatus.INTERNAL_SERVER_ERROR,ErrorCode.INTERNAL_ERROR,"An unexpected error occurred.",r,List.of());}private ResponseEntity<ApiError>make(HttpStatus s,ErrorCode c,String m,HttpServletRequest r,List<FieldViolation>v){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),c.name(),m,r.getRequestURI(),(String)r.getAttribute(NotificationRequestAttributes.CORRELATION_ID),v));}}
